    }

    answerAgentApproval(runId, requestId, decision) {
        return this.requireRun(runId).answerAgentApproval(requestId, decision);
    }

    finishAgentRun(runId) {
        this.requireRun(runId).finishAgent();
    }

    handleCardStateChange(cardInternalId, state) {
        for (const run of this.runs.values()) run.handleCardStateChange(cardInternalId, state);
    }

    requireActionsFolder() {
        if (!this.actionsFolder) throw new Error('Action runner has no actions folder');

        return this.actionsFolder;
    }

    requireProjectFolder() {
        if (this.projectFolder === null) throw new Error('Action runner has no projectFolder');
        if (this.releasesFolder === null) throw new Error('Action runner has no releasesFolder');

        return this.projectFolder;
    }

    async loadRootAction(actionId) {
        const config = this.agentConfigProvider();
        await this.actionCacheReady;

        return resolveActionDefinition(this.actionDefinitionCache, config.agentProfiles, actionId, this.configuredStates);
    }

    async finalizeRun(run, runCompletion) {
        const result = await runCompletion;
        this.runs.delete(run.runId);
        this.runEvents.delete(run.runId);
        this.completedRunResults.set(run.runId, result);
        return result;
    }

    publish(event) {
        const events = this.runEvents.get(event.runId);
        if (events) events.push(event);
        for (const listener of this.listeners) {
            try {
                listener(event);
            } catch (error) {
                this.reportError(error);
            }
        }
    }

    reportError(error) {
        try {
            this.errorReporter(error);
        } catch {
            // Error reporting must not affect action runs.
        }
    }

    requireRun(runId) {
        const run = this.runs.get(runId);
        if (!run) throw new Error(`Unknown action run: ${runId}`);

        return run;
    }

    requireReady() {
        this.requirePreparationReady();
        if (!this.agentRunnerService) throw new Error('Action runner has no agent runner service');
    }

    requirePreparationReady() {
        if (!this.project) throw new Error('Action runner has no project');
        if (!this.actionsFolder) throw new Error('Action runner has no actions folder');
        if (this.projectFolder === null) throw new Error('Action runner has no projectFolder');
        if (!this.localGitService) throw new Error('Action runner has no local Git service');
        if (!this.actionDefinitionCache) throw new Error('Action runner has no action definition cache');
        if (!this.actionCacheReady) throw new Error('Action runner action definition cache is not ready');
        if (!this.actionWorktreeRunService) throw new Error('Action runner has no worktree run service');
        if (!this.agentConfigProvider) throw new Error('Action runner has no agent config provider');
    }
}

module.exports = { ActionRunnerService };

import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'
import type { AgentConversationReservation, ActionRunInput, ActionRunResult } from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import { actionRunRegistry, cancelActionRun } from './action_run_registry'
import { dataService } from '../data/data_service'
import { projectPersistenceService } from '../project/project_persistence_service'

function shouldReserveConversation(action: ActionDefinition, context: ActionContext, input: ActionRunInput) {
    return action.type === 'agent'
        && !input.continueFrom
        && (context.kind === 'card' || context.kind === 'file')
        && !!context.cardInternalId
        && !!context.file
}

/** Start one persisted action through shared renderer run state. */
export async function runElectronAction(
    action: ActionDefinition,
    context: ActionContext,
    input: ActionRunInput = {},
    onStarted?: (runId: string) => void,
    interactive = true,
): Promise<ActionRunResult> {
    const handleStarted = (startedRunId: string) => {
        onStarted?.(startedRunId)
    }
    const requiresReservation = shouldReserveConversation(action, context, input)
    const bridge = getElectronActionBridge()
    const resumeAutomaticCommit = requiresReservation ? dataService.cards.deferAutomaticCommit() : null
    let conversationReservation: AgentConversationReservation | undefined
    try {
        conversationReservation = requiresReservation
            ? await bridge?.reserveActionConversation?.({ actionId: action.id, context, runInput: input })
            : undefined
        if (requiresReservation && !conversationReservation) {
            throw new Error('Starting a card agent requires conversation reservation support')
        }
        if (conversationReservation && context.file) {
            dataService.cards.addAgentLogReference(context.file, conversationReservation.reference)
        }
    } finally {
        resumeAutomaticCommit?.()
    }
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()
    return actionRunRegistry.startRun(action, context, input, handleStarted, interactive, conversationReservation)
}

/** Finish one idle streaming run, persist it, then continue through a new process. */
export async function restartElectronAction(
    previousRunId: string,
    action: ActionDefinition,
    context: ActionContext,
    input: ActionRunInput,
    onStarted?: (runId: string) => void,
): Promise<ActionRunResult> {
    if (projectPersistenceService.getSnapshot().hasPendingSave) await projectPersistenceService.flushPendingChanges()

    return actionRunRegistry.restartRun(previousRunId, action, context, input, onStarted)
}

export async function cancelElectronAction(runId: string) {
    await cancelActionRun(runId)
}

import { IconButton, ListItemIcon, MenuItem, Stack, Tooltip } from '@mui/material'
import { useEffect, useMemo, useState } from 'react'
import type { MouseEvent } from 'react'
import { displayActionsForContext, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { dialogService } from '../../../../services/dialog_service'
import { useActions } from '../../../hooks/use_actions'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { ActionIcon } from './action_icon'
import { resolveActionIcon, type ActionIconSource } from './action_icon_resolver'
import { ActionPopup } from '../popup/action_popup'

/** How action entry points are rendered in an existing toolbar or menu. */
export type ActionEntryVariant = 'icons' | 'menuItems'
export type ActionEntryVisibility = 'all-matching' | 'explicit-context'

interface ActionEntryPointsProps {
    context: ActionContext
    onMenuItemSelected?: () => void
    popupAnchorElement?: HTMLElement | null
    variant: ActionEntryVariant
    visibility?: ActionEntryVisibility
}

const DEFAULT_ICON_SOURCE: ActionIconSource = { dataUri: null }

interface ActionPopupState {
    actionId: string
    anchorElement: HTMLElement
}

/**
 * Context-sensitive action entry points shown close to a card/file/folder. Filters
 * the loaded actions by `appliesTo`, and on activation opens a resizable popup bound
 * to the action and context. `before`/`after` shortcuts push a new popup for the
 * related action with the same context.
 */
export function ActionEntryPoints(props: ActionEntryPointsProps) {
    const { context, onMenuItemSelected, popupAnchorElement, variant, visibility = 'all-matching' } = props
    const { actions: loadedActions } = useActions()
    const runningRun = useRunningActionForContext(context)
    const runDisabled = !!runningRun
    const [iconSources, setIconSources] = useState<Record<string, ActionIconSource>>({})
    const [popupState, setPopupState] = useState<ActionPopupState | null>(null)

    const matching = useMemo(() => {
        const contextActions = displayActionsForContext(loadedActions, context)
        if (visibility === 'explicit-context') {
            return contextActions.filter((action) => action.appliesTo?.kind === context.kind)
        }

        return contextActions
    }, [context, loadedActions, visibility])

    useEffect(() => {
        let isActive = true

        const loadIcons = async () => {
            const entries = await Promise.all(matching.map(async (action) => [action.id, await resolveActionIcon(action.icon)] as const))
            if (!isActive) return

            setIconSources(Object.fromEntries(entries))
        }

        void loadIcons()

        return () => {
            isActive = false
        }
    }, [matching])

    if (matching.length === 0) return null

    const open = (actionId: string, anchorElement: HTMLElement) => {
        onMenuItemSelected?.()
        setPopupState({ actionId, anchorElement })
    }

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        try {
            const { actionId } = event.currentTarget.dataset
            if (!actionId) throw new Error('Missing action id on action entry point')

            open(actionId, popupAnchorElement ?? event.currentTarget)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action popup could not be opened' })
        }
    }

    const iconSourceFor = (action: ActionDefinition) => iconSources[action.id] ?? DEFAULT_ICON_SOURCE

    const closePopup = () => {
        setPopupState(null)
    }

    const popup = popupState ? (
        <ActionPopup
            anchorElement={popupState.anchorElement}
            context={context}
            draggable
            initialActionId={popupState.actionId}
            key={popupState.actionId}
            onClose={closePopup}
        />
    ) : null

    const menuItems = (
        <>
            {matching.map((action) => (
                <MenuItem
                    data-action-id={action.id}
                    disabled={runDisabled}
                    key={action.id}
                    onClick={handleOpen}
                >
                    <ListItemIcon>
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </ListItemIcon>
                    {action.label}
                </MenuItem>
            ))}
            {popup}
        </>
    )

    if (variant === 'menuItems') return menuItems

    return (
        <Stack direction="row" spacing={0.25} sx={{ flexShrink: 0 }}>
            {matching.map((action) => (
                <Tooltip key={action.id} title={action.label}>
                    <IconButton
                        aria-label={action.label}
                        data-action-id={action.id}
                        disabled={runDisabled}
                        onClick={handleOpen}
                        size="small"
                    >
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </IconButton>
                </Tooltip>
            ))}
            {popup}
        </Stack>
    )
}

