import { ACTION_APPLIES_TO_FIELDS, CUSTOM_PROMPT_ACTION_ID } from './action_types'
import type { ActionAppliesToField, ActionDefinition } from './action_types'
import type { Card, CardHeader, CardTypeConfig } from './data_types'
import { getCardIdPrefix } from './card_identifiers'

/** The kind of item an action entry point is attached to. */
export type ActionContextKind = 'card' | 'file' | 'folder' | 'project'

export type ActionContextFilterValueSource =
    'kind' | 'type' | 'state' | 'file' | 'folder' | 'worktree' | 'text'

export interface ActionContextFilterDescriptor {
    key: ActionAppliesToField
    label: string
    supportedContextKinds: ActionContextKind[]
    valueSource: ActionContextFilterValueSource
    validate: (value: string) => string | null
}

/**
 * The selected item an action is evaluated against. `appliesTo` keys are matched
 * field-by-field against this object, so every matchable property is a string.
 */
export interface ActionContext {
    /** Stable card identity used for activity ownership. */
    cardInternalId?: string
    /** Title of the selected card, used for placeholder resolution. */
    title?: string
    /** Card/file type derived from the id prefix, e.g. `feature`. */
    type?: string
    /** Card state / status, e.g. `design`. */
    state?: string
    /** Path to the markdown file, used for placeholder resolution. */
    file?: string
    /** Folder name for folder contexts. */
    folder?: string
    kind: ActionContextKind
    worktree?: string
    worktreeError?: string
    [key: string]: string | undefined
}

/**
 * Stable identity of the item an action runs against, used to match a popup to its
 * execution and conversation history. Mutable header fields (title, state, worktree)
 * are excluded on purpose: a run that edits its own card must keep the same identity.
 */
export function actionContextIdentity(context: ActionContext): string {
    if (context.kind === 'project') return 'project'
    if (context.kind === 'folder') return `folder�${context.folder ?? ''}`

    return `${context.kind}�${context.cardInternalId ?? context.file ?? ''}`
}

/** Required-value validation shared by every applicability filter descriptor. */
export function validateActionContextFilterValue(value: string): string | null {
    return value.length > 0 ? null : 'Required value'
}

const ACTION_CONTEXT_FILTER_METADATA: Record<ActionAppliesToField, Omit<ActionContextFilterDescriptor, 'key'>> = {
    file: { label: 'Repository file', supportedContextKinds: ['card', 'file'], valueSource: 'file', validate: validateActionContextFilterValue },
    folder: { label: 'Repository folder', supportedContextKinds: ['folder'], valueSource: 'folder', validate: validateActionContextFilterValue },
    kind: { label: 'Target kind', supportedContextKinds: ['card', 'file', 'folder', 'project'], valueSource: 'kind', validate: validateActionContextFilterValue },
    state: { label: 'Card state', supportedContextKinds: ['card', 'file'], valueSource: 'state', validate: validateActionContextFilterValue },
    type: { label: 'Context type', supportedContextKinds: ['card', 'file', 'folder'], valueSource: 'type', validate: validateActionContextFilterValue },
    worktree: { label: 'Worktree', supportedContextKinds: ['card', 'file', 'project'], valueSource: 'worktree', validate: validateActionContextFilterValue },
    worktreeError: { label: 'Worktree error', supportedContextKinds: ['card', 'file'], valueSource: 'text', validate: validateActionContextFilterValue },
}

export const ACTION_CONTEXT_FILTER_DESCRIPTORS: ActionContextFilterDescriptor[] = ACTION_APPLIES_TO_FIELDS.map((key) => ({
    key,
    ...ACTION_CONTEXT_FILTER_METADATA[key],
}))

/** Resolve the configured card type for a card id via its prefix (e.g. `F-005` â†’ `feature`). */
export function getCardType(cardTypes: CardTypeConfig[], id: string): string | undefined {
    const prefix = getCardIdPrefix(id)

    return cardTypes.find((cardType) => cardType.idPrefix === prefix)?.type
}

type MarkdownContextCard = Pick<Card, 'path'> & {
    header: Pick<CardHeader, 'id' | 'internalId' | 'status' | 'title' | 'worktreeError' | 'worktreeValue'>
}

function markdownContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[], kind: ActionContextKind): ActionContext {
    const context: ActionContext = { file: card.path, kind, title: card.header.title }
    const type = getCardType(cardTypes, card.header.id)
    if (card.header.internalId) context.cardInternalId = card.header.internalId
    if (type) context.type = type
    if (card.header.status) context.state = card.header.status
    if (card.header.worktreeValue) context.worktree = card.header.worktreeValue
    if (card.header.worktreeError) context.worktreeError = card.header.worktreeError

    return context
}

/** Build the action context for a card shown in card view. */
export function cardContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[]): ActionContext {
    if (!card.header.internalId) throw new Error(`Cannot build action context without an internal ID: ${card.path}`)

    return markdownContext(card, cardTypes, 'card')
}

/**
 * Build the action context for a markdown file in the tree/text view. Regular markdown files
 * are not cards and carry no internal ID, so the context stays without card identity.
 */
export function fileContext(card: Card, cardTypes: CardTypeConfig[]): ActionContext {
    return markdownContext(card, cardTypes, 'file')
}

/** Build the action context for a folder node in the tree. */
export function folderContext(folder: string, isSpecial = false): ActionContext {
    const context: ActionContext = { folder, kind: 'folder' }
    if (isSpecial) context.type = folder

    return context
}

/** Build context for actions that run against the opened project rather than a card or file. */
export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree

        return unassignedContext
    }

    return { ...context, worktree: String(worktree) }
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || context[key] === action.appliesTo[key])
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

import AddOutlined from '@mui/icons-material/AddOutlined'
import DeleteOutlineOutlined from '@mui/icons-material/DeleteOutlineOutlined'
import { Box, Button, IconButton, MenuItem, Stack, Tooltip, Typography } from '@mui/material'
import { useEffect, useState, type ChangeEvent, type MouseEvent } from 'react'
import {
    ACTION_CONTEXT_FILTER_DESCRIPTORS,
    type ActionContextFilterDescriptor,
} from '../../../data/action_context'
import type { ActionAppliesTo, ActionAppliesToField } from '../../../data/action_types'
import type { WorktreeRecord } from '../../../data/data_types'
import { dialogService } from '../../../services/dialog_service'
import { ActionEditorField } from './action_editor_field'
import { ActionSectionLabel } from '../shared/action_section_label'
import { ActionEditorTextField } from './action_editor_text_field'

interface FilterOption {
    label: string
    value: string
}

interface PendingFilter {
    field: ActionAppliesToField
    index: number
}

interface ActionFilterEditorProps {
    cardTypes: string[]
    error?: string
    onChange: (filters: ActionAppliesTo | undefined) => void
    repositoryFiles: string[]
    specialContextTypes: string[]
    states: string[]
    value: ActionAppliesTo | undefined
    worktrees: WorktreeRecord[]
}

function uniqueOptions(values: string[]): FilterOption[] {
    return [...new Set(values)].map((value) => ({ label: value, value }))
}

function repositoryFolderNames(repositoryFiles: string[]): string[] {
    const folders = repositoryFiles.flatMap((path) => path.replace(/\\/gu, '/').split('/').slice(0, -1))

    return [...new Set(folders)]
}

function optionsForDescriptor(
    descriptor: ActionContextFilterDescriptor,
    props: ActionFilterEditorProps,
): FilterOption[] {
    const { cardTypes, repositoryFiles, specialContextTypes, states, worktrees } = props
    if (descriptor.valueSource === 'kind') return uniqueOptions(['card', 'file', 'folder', 'project'])
    if (descriptor.valueSource === 'type') return uniqueOptions([...cardTypes, ...specialContextTypes])
    if (descriptor.valueSource === 'state') return uniqueOptions(states)
    if (descriptor.valueSource === 'file') return uniqueOptions(repositoryFiles)
    if (descriptor.valueSource === 'folder') return uniqueOptions(repositoryFolderNames(repositoryFiles))
    if (descriptor.valueSource === 'worktree') {
        return worktrees.map(({ error, path }, index) => ({
            label: error ? `${index + 1} â€” ${path} (${error})` : `${index + 1} â€” ${path}`,
            value: String(index + 1),
        }))
    }

    return []
}

function includeCurrentOption(options: FilterOption[], value: string): FilterOption[] {
    if (!value || options.some((option) => option.value === value)) return options

    return [{ label: `${value} (current)`, value }, ...options]
}

function replaceEntry(
    entries: [ActionAppliesToField, string][],
    index: number,
    field: ActionAppliesToField,
    fieldValue: string,
): ActionAppliesTo {
    return Object.fromEntries(entries.map((entry, entryIndex) => (
        entryIndex === index ? [field, fieldValue] : entry
    )))
}

export function ActionFilterEditor(props: ActionFilterEditorProps) {
    const { error, onChange, value } = props
    const [pendingFilter, setPendingFilter] = useState<PendingFilter | null>(null)
    const persistedEntries = Object.entries(value ?? {}) as [ActionAppliesToField, string][]
    const entries: [ActionAppliesToField, string][] = pendingFilter
        ? persistedEntries.map((entry, index) => index === pendingFilter.index ? [pendingFilter.field, ''] : entry)
        : persistedEntries
    if (pendingFilter?.index === persistedEntries.length) entries.push([pendingFilter.field, ''])
    const descriptorByKey = new Map(ACTION_CONTEXT_FILTER_DESCRIPTORS.map((descriptor) => [descriptor.key, descriptor]))
    const missingDescriptorFields = entries
        .map(([field]) => field)
        .filter((field) => !descriptorByKey.has(field))
    const missingDescriptorMessage = missingDescriptorFields.length > 0
        ? `Missing applicability filter descriptor: ${missingDescriptorFields.join(', ')}`
        : null
    const hasIncompleteRow = entries.some(([field, fieldValue]) => !field || !fieldValue)
    const hasEveryFilter = entries.length === ACTION_CONTEXT_FILTER_DESCRIPTORS.length

    useEffect(() => {
        if (missingDescriptorMessage) dialogService.error(missingDescriptorMessage)
    }, [missingDescriptorMessage])

    const handleAdd = () => {
        try {
            const descriptor = ACTION_CONTEXT_FILTER_DESCRIPTORS.find(({ key }) => !entries.some(([field]) => field === key))
            if (!descriptor) throw new Error('No applicability filter available')
            setPendingFilter({ field: descriptor.key, index: entries.length })
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Applicability filter could not be added' })
        }
    }

    const handleFieldChange = (event: ChangeEvent<HTMLInputElement>) => {
        try {
            const index = Number.parseInt(event.target.name, 10)
            const previousEntry = entries[index]
            if (!previousEntry) throw new Error(`Missing applicability filter at index ${index}`)

            setPendingFilter({ field: event.target.value as ActionAppliesToField, index })
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Applicability filter field could not be changed' })
        }
    }

    const handleValueChange = (event: ChangeEvent<HTMLInputElement>) => {
        try {
            const index = Number.parseInt(event.target.name, 10)
            const entry = entries[index]
            if (!entry) throw new Error(`Missing applicability filter at index ${index}`)

            const [field] = entry
            const nextFilters = index === persistedEntries.length
                ? { ...value, [field]: event.target.value }
                : replaceEntry(persistedEntries, index, field, event.target.value)
            onChange(nextFilters)
            setPendingFilter(null)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Applicability filter value could not be changed' })
        }
    }

    const handleRemove = (event: MouseEvent<HTMLButtonElement>) => {
        try {
            const index = Number.parseInt(event.currentTarget.dataset.index ?? '', 10)
            const entry = entries[index]
            if (!entry) throw new Error(`Missing applicability filter at index ${index}`)

            const nextEntries = persistedEntries.filter((_entry, entryIndex) => entryIndex !== index)
            setPendingFilter(null)
            if (pendingFilter?.index === persistedEntries.length) return
            onChange(nextEntries.length > 0 ? Object.fromEntries(nextEntries) : undefined)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Applicability filter could not be removed' })
        }
    }

    return (
        <Stack spacing={1}>
            <ActionSectionLabel>Applicability filters</ActionSectionLabel>
            {entries.length === 0 ? (
                <Typography color="custom.text4" variant="caption">
                    No filters. The action is available in every context.
                </Typography>
            ) : null}
            {entries.map(([field, fieldValue], index) => {
                const descriptor = descriptorByKey.get(field)
                if (!descriptor) return null
                const valueError = pendingFilter?.index === index ? null : descriptor.validate(fieldValue)
                const options = includeCurrentOption(optionsForDescriptor(descriptor, props), fieldValue)

                return (
                    <Box
                        aria-label={'Applicability filter ' + (index + 1)}
                        key={index}
                        role="group"
                        sx={{
                            alignItems: 'start',
                            display: 'grid',
                            gap: 1,
                            gridTemplateColumns: { sm: 'minmax(0, 1fr) minmax(0, 1fr) auto', xs: 'minmax(0, 1fr)' },
                            minWidth: 0,
                            '&:focus-within .action-row-actions, &:hover .action-row-actions': { opacity: 1 },
                        }}
                    >
                        <ActionEditorField
                            fieldId={'action-filter-field-' + index}
                            label="Context field"
                            name={String(index)}
                            onChange={handleFieldChange}
                            select
                            size="small"
                            value={field}
                        >
                            {ACTION_CONTEXT_FILTER_DESCRIPTORS.map((option) => (
                                <MenuItem
                                    disabled={entries.some(([entryField]) => entryField === option.key) && option.key !== field}
                                    key={option.key}
                                    value={option.key}
                                >
                                    {option.label}
                                </MenuItem>
                            ))}
                        </ActionEditorField>
                        {descriptor.valueSource === 'text' ? (
                            <ActionEditorTextField
                                error={!!valueError || !!error}
                                fieldId={'action-filter-value-' + index}
                                helperText={valueError ?? error}
                                label={descriptor.label}
                                name={String(index)}
                                onChange={handleValueChange}
                                size="small"
                                source={value as ActionAppliesTo}
                                value={fieldValue}
                            />
                        ) : (
                            <ActionEditorField
                                error={!!valueError || !!error}
                                fieldId={'action-filter-value-' + index}
                                helperText={valueError ?? error}
                                label={descriptor.label}
                                name={String(index)}
                                onChange={handleValueChange}
                                select
                                size="small"
                                value={fieldValue}
                            >
                                {options.map((option) => <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>)}
                            </ActionEditorField>
                        )}
                        <Box className="action-row-actions" sx={{ display: 'flex', justifyContent: 'flex-end', opacity: 0 }}>
                            <Tooltip title={`Remove ${field || 'custom'} filter`}>
                                <IconButton
                                    aria-label={`Remove ${field || 'custom'} filter`}
                                    data-index={index}
                                    onClick={handleRemove}
                                    size="small"
                                    sx={{ '&:focus-visible, &:hover': { bgcolor: 'action.hover', color: 'primary.main' } }}
                                >
                                    <DeleteOutlineOutlined fontSize="small" />
                                </IconButton>
                            </Tooltip>
                        </Box>
                    </Box>
                )
            })}
            <Button disabled={hasIncompleteRow || hasEveryFilter} onClick={handleAdd} size="small" startIcon={<AddOutlined />} sx={{ alignSelf: 'flex-start' }} variant="outlined">
                Add filter
            </Button>
        </Stack>
    )
}

import type { ActionContext } from '../../data/action_context'
import type { ActionDefinition } from '../../data/action_types'

const FOLDER_PLACEHOLDER_NAMES = 'worktree-folder|repository-folder|project-folder|releases-folder'
const CARD_PLACEHOLDER_NAMES = 'card-file|card-title|card-prompt'
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu')
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u

export interface ActionFolderPlaceholderValues {
    projectFolder: string
    repositoryFolder: string
    releasesFolder: string
    worktreeFolder: string
}

export function resolvePlaceholders(
    text: string,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name: string) => {
        if (name === 'worktree-folder') {
            if (!folders.worktreeFolder) throw new Error('Cannot resolve worktree-folder without a run checkout path')

            return folders.worktreeFolder
        }
        if (name === 'repository-folder') {
            if (!folders.repositoryFolder) throw new Error('Cannot resolve repository-folder without an opened repository path')

            return folders.repositoryFolder
        }
        if (name === 'project-folder') {
            if (!folders.projectFolder) throw new Error('Cannot resolve project-folder without a configured project path')

            return folders.projectFolder
        }
        if (name === 'releases-folder') {
            if (!folders.releasesFolder) throw new Error('Cannot resolve releases-folder without a configured releases folder')

            return folders.releasesFolder
        }

        if (name === 'card-prompt') return extraPrompt

        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title')

            return context.title
        }

        if (!context.file) throw new Error('Cannot resolve card-file placeholder without a file context')

        return context.file
    })
}

export function resolveAgentPrompt(
    action: ActionDefinition,
    context: ActionContext,
    folders: ActionFolderPlaceholderValues,
    extraPrompt: string,
): string {
    if (!action.prompt) throw new Error(`Missing prompt for agent action "${action.label}"`)
    const resolvedText = resolvePlaceholders(action.prompt, context, folders, extraPrompt)
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt)) return resolvedText
    if (extraPrompt.trim().length === 0) return resolvedText

    return `${resolvedText}\n\n${extraPrompt}`
}

const path = require('node:path');
const { requireRootPath } = require('../../git/git_commands');

const FOLDER_PLACEHOLDER_NAMES = 'worktree-folder|repository-folder|project-folder|releases-folder';
const CARD_PLACEHOLDER_NAMES = 'card-file|this-card|card-title|card-prompt';
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${FOLDER_PLACEHOLDER_NAMES}|${CARD_PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu');
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u;
const TRACKED_FILE_COMMIT_INSTRUCTION = 'Do not stage or commit changes. md2 will commit files captured from provider edit tools.';

function resolvePlaceholders(text, context, runProject, primaryProject, projectFolder, releasesFolder, extraPrompt) {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name) => {
        if (name === 'worktree-folder') return requireRootPath(runProject);
        if (name === 'repository-folder') return requireRootPath(primaryProject);
        if (name === 'project-folder') {
            if (typeof projectFolder !== 'string') {
                throw new Error('Cannot resolve project-folder placeholder without a configured project folder');
            }

            const repositoryFolder = requireRootPath(primaryProject);

            return projectFolder.length === 0 ? repositoryFolder : path.resolve(repositoryFolder, projectFolder);
        }
        if (name === 'releases-folder') {
            if (typeof releasesFolder !== 'string' || releasesFolder.length === 0) {
                throw new Error('Cannot resolve releases-folder placeholder without a configured releases folder');
            }

            return path.resolve(requireRootPath(primaryProject), releasesFolder);
        }
        if (name === 'card-prompt') return extraPrompt;
        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title');

            return context.title;
        }
        if (!context.file) throw new Error(`Cannot resolve ${name} placeholder without a file context`);

        return context.file;
    });
}

function resolveAgentPrompt(action, context, runProject, primaryProject, projectFolder, releasesFolder, extraPrompt) {
    const prompt = resolvePlaceholders(action.prompt, context, runProject, primaryProject, projectFolder, releasesFolder, extraPrompt);
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt) || extraPrompt.trim().length === 0) return prompt;

    return `${prompt}\n\n${extraPrompt}`;
}

function withTrackedFileCommitInstruction(prompt, trackFileChanges) {
    return trackFileChanges ? `${prompt}\n\n${TRACKED_FILE_COMMIT_INSTRUCTION}` : prompt;
}

function prepareAgentPrompt(action, context, runProject, primaryProject, projectFolder, releasesFolder, extraPrompt = '') {
    const prompt = resolveAgentPrompt(action, context, runProject, primaryProject, projectFolder, releasesFolder, extraPrompt);

    return withTrackedFileCommitInstruction(prompt, action.trackFileChanges);
}

module.exports = { prepareAgentPrompt, resolveAgentPrompt, resolvePlaceholders, withTrackedFileCommitInstruction };

