    'project.cardSeparator',
    'project.cardTypes',
    'project.states',
]

export const LOCAL_STORAGE_KEYS: ConfigKey[] = CONFIG_ENTRIES.filter(
    (entry) => entry.source === 'react',
).map((entry) => entry.key)

export function createDefaultValues(): ConfigValues {
    return CONFIG_ENTRIES.reduce((values, entry) => ({ ...values, [entry.key]: entry.defaultValue }), {} as ConfigValues)
}

export function requireConfigEntry(key: ConfigKey) {
    const entry = CONFIG_ENTRY_BY_KEY.get(key)
    if (!entry) throw new Error(`Unknown config key: ${key}`)

    return entry
}

import type { DesktopConfigValues } from './config_entries'

export interface ElectronConfigBridge {
    getDesktopConfig(): Partial<DesktopConfigValues>
    setDesktopConfig(values: DesktopConfigValues): void
}

declare global {
    interface Window {
        md2Config?: ElectronConfigBridge
    }
}

export function getElectronConfigBridge() {
    return window.md2Config ?? null
}

import type { ConfigSectionProps } from './config_section_props'
import { ConfigSectionLayout } from './config_section_layout'

const DESKTOP_CONFIG_SECTION_ID = 'desktop'
const DESKTOP_CONFIG_SECTION_LABEL = 'Desktop'

interface DesktopConfigSectionProps extends ConfigSectionProps {
    disabled: boolean
}

export function DesktopConfigSection(props: DesktopConfigSectionProps) {
    const { disabled, draft, entries, onChange, onValidityChange } = props
    const sectionEntries = entries.filter((entry) => entry.section === DESKTOP_CONFIG_SECTION_ID)

    return (
        <ConfigSectionLayout
            disabled={disabled}
            draft={draft}
            entries={sectionEntries}
            id={DESKTOP_CONFIG_SECTION_ID}
            label={DESKTOP_CONFIG_SECTION_LABEL}
            onChange={onChange}
            onValidityChange={onValidityChange}
        />
    )
}

