        trackFileChanges: false,
        streaming: false,
        type: 'command',
    }
}

function card(id: string, status: string | null): Card {
    return {
        agentConversationErrors: [],
        agentConversations: [],
        content: '',
        header: {
            affects: [], after: null, agentLogReferences: [], author: null, id, internalId: id.toLowerCase(), owner: null,
