const { contextBridge, ipcRenderer } = require('electron');

const CONFIG_SET_DESKTOP_CHANNEL = 'md2-config:set-desktop';
const LIFECYCLE_FLUSH_DONE_CHANNEL = 'md2-lifecycle:flush-pending-commits-done';
const LIFECYCLE_FLUSH_REQUEST_CHANNEL = 'md2-lifecycle:flush-pending-commits';
const LOCAL_BRIDGE_EVENT_CHANNEL = 'md2-local-bridge:event';
const LOCAL_BRIDGE_INVOKE_CHANNEL = 'md2-local-bridge:invoke';
const LOCAL_BRIDGE_SUBSCRIBE_CHANNEL = 'md2-local-bridge:subscribe';
const LOCAL_BRIDGE_UNSUBSCRIBE_CHANNEL = 'md2-local-bridge:unsubscribe';
const REMARKABLE_IMPORT_FILES_CHANNEL = 'md2-remarkable:import-files';
const REMARKABLE_LIST_IMAGE_FILES_CHANNEL = 'md2-remarkable:list-image-files';
const REMARKABLE_TEST_CONNECTION_CHANNEL = 'md2-remarkable:test-connection';
const REMOTE_CONTROL_GET_STATUS_CHANNEL = 'md2-remote-control:get-status';
const REMOTE_CONTROL_START_CHANNEL = 'md2-remote-control:start';
const REMOTE_CONTROL_STATUS_CHANNEL = 'md2-remote-control:status';
const REMOTE_CONTROL_STOP_CHANNEL = 'md2-remote-control:stop';
const THEME_SET_MODE_CHANNEL = 'md2-theme:set-mode';

const DATA_METHODS = [
    'addWorktree',
    'cancelActionSchedule',
    'checkoutBranch',
    'commit',
    'commitWorktree',
    'createProject',
    'deleteFile',
    'deleteFolder',
    'discardWorktreeChanges',
    'deleteLocalBranch',
    'hasPendingPush',
    'integrateWorktree',
    'listBranches',
    'listAgentConversationReferences',
    'listRepositoryFiles',
    'listTopLevelFolders',
    'loadActionFiles',
    'loadActionSchedules',
    'loadAgentAvailability',
    'loadAgentConversation',
    'loadFile',
    'loadProject',
    'loadProjectAsset',
    'loadProjectConfig',
    'loadProjectRoot',
    'loadTextFile',
    'moveFiles',
    'openProjectFolder',
    'parkWorktree',
    'prepareWorktree',
    'pull',
    'pullWorktree',
    'push',
    'pushWorktree',
    'rebaseWorktree',
    'refreshWorktrees',
    'removeWorktree',
    'resolveProject',
    'saveActionSchedules',
    'saveProjectConfig',
    'stopAgent',
];
const ACTION_METHODS = [
    'answerActionApproval',
    'answerActionQuestion',
    'beginActionPromptDraft',
    'cancelActionRun',
    'closeWaitingActionConversation',
    'finishActionRun',
    'generateDiff',
    'generateWorktreeDiff',
    'loadActionRunHistory',
    'loadActiveActionRunEvents',
    'notifyActionCardStateChange',
    'loadCardActivity',
    'loadAgentAvailability',
    'openInEditor',
    'prepareActionPrompt',
    'readFileAtCommit',
    'registerActionSchedule',
    'reserveActionConversation',
    'restartActionRun',
    'runSearchRegexpAgent',
    'sendActionMessage',
    'sendActionQueuedMessage',
    'setActionQueuedMessage',
    'startAction',
    'startUnattendedAction',
    'updateActionConversationViewed',
    'updateCardActionSettings',
];
const EVENT_METHODS = new Set(['runSearchRegexpAgent']);
const CODEX_RUNTIME_METHODS = ['getCodexRateLimits'];

let nextEventId = 1;
let desktopConfig = readArgumentJson('md2-desktop-config', {});

function readArgumentValue(name) {
    const prefix = `--${name}=`;
    const argument = process.argv.find((candidate) => candidate.startsWith(prefix));

    return argument ? argument.slice(prefix.length) : null;
}

function readArgumentJson(name, fallback) {
    const value = readArgumentValue(name);
    if (!value) return fallback;

    return JSON.parse(decodeURIComponent(value));
}

function createEventId(method) {
    const eventId = `${method}-${nextEventId}`;
    nextEventId += 1;

    return eventId;
}

function invokeBridge(method, params, callback) {
    const eventId = EVENT_METHODS.has(method) && callback ? createEventId(method) : null;
    let listener = null;

    if (eventId) {
        listener = (_event, message) => {
            if (message.eventId === eventId) callback(message.payload);
        };
        ipcRenderer.on(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
    }

    return ipcRenderer.invoke(LOCAL_BRIDGE_INVOKE_CHANNEL, { eventId, method, params }).finally(() => {
        if (listener) ipcRenderer.removeListener(LOCAL_BRIDGE_EVENT_CHANNEL, listener);
        try {
            request = JSON.parse(rawMessage.toString());
        } catch {
            sendJson(client, { error: { message: 'Invalid remote-control JSON message' }, id: null });
            return;
        }

        const { id, method, params = [] } = request;
        try {
            const result = await this.invoke(client, method, params, id);
            sendJson(client, { id, result });
        } catch (error) {
            sendJson(client, { error: { message: errorMessage(error) }, id });
        }
    }

    async invoke(client, method, params, id) {
        if (method === 'unsubscribe') return this.unsubscribe(client, params);
        if (method === 'onActionRun') return this.onActionRun(client, id);
        if (method === 'onCodexRateLimits') return this.onCodexRateLimits(client, id);
        if (method === 'onWorktreesChanged') return this.onWorktreesChanged(client, id);
        if (method === 'watchProject') return this.watchProject(client, params, id);
        if (!this.dispatcher) throw new Error('Remote-control dispatch is not configured');
        if (AGENT_EVENT_METHODS.has(method)) {
            return this.dispatcher.invoke(method, [...params, (event) => sendJson(client, { event: 'agentRun', payload: { event, requestId: id } })]);
        }

        return this.dispatcher.invoke(method, params);
    }

    watchProject(client, params, id) {
        if (!this.dispatcher) throw new Error('Remote-control dispatch is not configured');
        if (!Array.isArray(params)) throw new Error('Remote-control params must be an array');

        const subscriptionId = crypto.randomUUID();
        const cleanup = this.dispatcher.invoke('watchProject', [
            params[0],
            (event) => sendJson(client, { event: 'watchProject', payload: { event, requestId: id, subscriptionId } }),
        ]);
        this.addSubscription(client, subscriptionId, cleanup);

        return { subscriptionId };
    }

    onActionRun(client, id) {
        if (!this.dispatcher) throw new Error('Remote-control dispatch is not configured');

        const subscriptionId = crypto.randomUUID();
        const cleanup = this.dispatcher.invoke('onActionRun', [
            (event) => sendJson(client, { event: 'actionRun', payload: { event, requestId: id, subscriptionId } }),
        ]);
        this.addSubscription(client, subscriptionId, cleanup);

        return { subscriptionId };
    }

    onCodexRateLimits(client, id) {
        if (!this.dispatcher) throw new Error('Remote-control dispatch is not configured');

        const subscriptionId = crypto.randomUUID();
        const cleanup = this.dispatcher.invoke('onCodexRateLimits', [
            (snapshot) => sendJson(client, {
                event: 'codexRateLimits',
                payload: { requestId: id, snapshot, subscriptionId },
            }),
        ]);
        this.addSubscription(client, subscriptionId, cleanup);

        return { subscriptionId };
    }

    onWorktreesChanged(client, id) {
        if (!this.dispatcher) throw new Error('Remote-control dispatch is not configured');

        const subscriptionId = crypto.randomUUID();
        const cleanup = this.dispatcher.invoke('onWorktreesChanged', [
            (state) => sendJson(client, { event: 'worktreesChanged', payload: { requestId: id, state, subscriptionId } }),
        ]);
        this.addSubscription(client, subscriptionId, cleanup);

        return { subscriptionId };
    }

    unsubscribe(client, params) {
        if (!Array.isArray(params) || typeof params[0] !== 'string') throw new Error('Missing subscription id');

        return this.removeSubscription(client, params[0]);
    }

    addSubscription(client, subscriptionId, cleanup) {
        const subscriptions = this.subscriptions.get(client) ?? new Map();
        subscriptions.set(subscriptionId, cleanup);
        this.subscriptions.set(client, subscriptions);
    }

    removeSubscription(client, subscriptionId) {
    }

    async stopAgent(_project: ProjectReference, runId: string): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.stopAgent) throw new Error('Electron local Git bridge cannot stop agents')

        await bridge.stopAgent(runId)
    }

    async loadProjectConfig(project: ProjectReference): Promise<Partial<ProjectConfig> | null> {
        return this.requireBridge().loadProjectConfig(project)
    }

    onWorktreesChanged(callback: (state: WorktreeState) => void) {
        const bridge = this.requireBridge()
        if (!bridge.onWorktreesChanged) throw new Error('Electron local Git bridge cannot subscribe to worktrees')

        return bridge.onWorktreesChanged(callback)
    }

    async listBranches(project: ProjectReference): Promise<BranchReference[]> {
        return this.requireBridge().listBranches(project)
    }

    async listRepositories(): Promise<RepositoryReference[]> {
        this.requireBridge()

        return []
    }

    async listRepositoryFiles(project: ProjectReference): Promise<string[]> {
        return this.requireBridge().listRepositoryFiles(project)
    }

    async listAgentConversationReferences(project: ProjectReference, projectFolder: string): Promise<string[]> {
        const bridge = this.requireBridge()
        if (!bridge.listAgentConversationReferences) throw new Error('Electron local Git bridge cannot list agent conversations')

        return bridge.listAgentConversationReferences(project, projectFolder)
    }

    async listTopLevelFolders(project: ProjectReference): Promise<TopLevelFolderReference[]> {
        return this.requireBridge().listTopLevelFolders(project)
    }

    async loadPendingPush(project: ProjectReference) {
        const hasPendingPush = await this.requireBridge().hasPendingPush(project)
        if (hasPendingPush) this.pendingPushBranches.add(project.branch)
        else this.pendingPushBranches.delete(project.branch)
    }

    async integrateWorktree(request: WorktreeOperationRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.integrateWorktree) throw new Error('Electron local Git bridge cannot integrate worktrees')

        await bridge.integrateWorktree(request)
        this.pendingPushBranches.add(request.project.branch)
    }

    async checkoutBranch(project: ProjectReference, branch: string): Promise<ProjectReference> {
        return this.requireBridge().checkoutBranch(project, branch)
    }

    async commit(request: CommitRequest): Promise<CommitResult> {
        await this.requireBridge().commit(request)
        this.pendingPushBranches.add(request.branch)

        return []
    }

    async commitWorktree(request: CommitWorktreeRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.commitWorktree) throw new Error('Electron local Git bridge cannot commit worktree changes')

        await bridge.commitWorktree(request)
    }

    async deleteFile(request: DeleteFileRequest): Promise<void> {
        await this.requireBridge().deleteFile(request)
        this.pendingPushBranches.add(request.branch)
    }

    async deleteFolder(request: DeleteFolderRequest): Promise<void> {
        await this.requireBridge().deleteFolder(request)
        this.pendingPushBranches.add(request.branch)
    }

    async deleteLocalBranch(project: ProjectReference, branchName: string): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.deleteLocalBranch) throw new Error('Electron local Git bridge cannot delete local branches')

        await bridge.deleteLocalBranch(project, branchName)
    }

    async discardWorktreeChanges(request: WorktreeOperationRequest): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.discardWorktreeChanges) throw new Error('Electron local Git bridge cannot discard worktree changes')

        await bridge.discardWorktreeChanges(request)
    }

    async moveFiles(request: MoveFilesRequest): Promise<void> {
        await this.requireBridge().moveFiles(request)
        this.pendingPushBranches.add(request.branch)
    }

    async push(project: ProjectReference): Promise<void> {
        await this.requireBridge().push(project)
        this.pendingPushBranches.delete(project.branch)
    }

    async pull(project: ProjectReference): Promise<void> {
        const bridge = this.requireBridge()
        if (!bridge.pull) throw new Error('Electron local Git bridge cannot pull the primary worktree')

        await bridge.pull(project)
    }

