import { useSyncExternalStore } from 'react'
import {
    ACTIONS_CHANGED_EVENT,
    actionService,
    type ActionService,
    type ActionServiceState,
} from '../../services/actions/action_service'

const snapshots = new WeakMap<ActionService, ActionServiceState>()

function isSameActionServiceState(first: ActionServiceState, second: ActionServiceState) {
    return first.actions === second.actions && first.error === second.error
}

function getActionServiceSnapshot(service: ActionService): ActionServiceState {
    const nextSnapshot = service.getState()
    const currentSnapshot = snapshots.get(service)
    if (currentSnapshot && isSameActionServiceState(currentSnapshot, nextSnapshot)) return currentSnapshot

    snapshots.set(service, nextSnapshot)

    return nextSnapshot
}

/** Subscribe to the loaded action definitions exposed by the action service. */
export function useActions(service: ActionService = actionService): ActionServiceState {
    return useSyncExternalStore(
        (onStoreChange) => {
            service.addEventListener(ACTIONS_CHANGED_EVENT, onStoreChange)

            return () => service.removeEventListener(ACTIONS_CHANGED_EVENT, onStoreChange)
        },
        () => getActionServiceSnapshot(service),
        () => getActionServiceSnapshot(service),
    )
}

import { Alert, Button, Dialog, DialogActions, DialogContent, DialogTitle, Snackbar } from '@mui/material'
import type { SyntheticEvent } from 'react'
import { useEffect, useState } from 'react'
import { DIALOG_SERVICE_EVENT, dialogService, type DialogServiceMessage } from '../services/dialog_service'
import { SelectableAlertMessage } from './selectable_alert_message'
import { GlobalProgressBackdrop } from './global_progress_backdrop'

// const SNACKBAR_AUTO_HIDE_MS = 6000
const IMMEDIATE_TRANSITION_MS = 0
const SNACKBAR_TRANSITION_DURATION_MS = { exit: IMMEDIATE_TRANSITION_MS }

/** Renders dialog service events as snackbars or blocking dialogs. */
export function DialogDisplay() {
    const [dialogMessage, setDialogMessage] = useState<DialogServiceMessage | null>(null)
    const [snackbarMessages, setSnackbarMessages] = useState<DialogServiceMessage[]>([])
    const snackbarMessage = snackbarMessages[0] ?? null
    const snackbarSeverity = snackbarMessage?.severity ?? 'info'
    const snackbarAutoHideDuration = null; // temp test snackbarSeverity === 'error' ? null : SNACKBAR_AUTO_HIDE_MS
    const dialogSeverity = dialogMessage?.severity ?? 'info'

    useEffect(() => {
        const handleDialogMessage = (event: Event) => {
            const message = (event as CustomEvent<DialogServiceMessage>).detail
            if (message.critical) setDialogMessage(message)
            else setSnackbarMessages((currentMessages) => [...currentMessages, message])
        }

        dialogService.addEventListener(DIALOG_SERVICE_EVENT, handleDialogMessage)

        return () => dialogService.removeEventListener(DIALOG_SERVICE_EVENT, handleDialogMessage)
    }, [])

    const handleCloseSnackbar = (_event: Event | SyntheticEvent, reason?: string) => {
        if (reason === 'clickaway') return

        setSnackbarMessages((currentMessages) => currentMessages.slice(1))
    }

    const handleCloseSnackbarAlert = () => {
        setSnackbarMessages((currentMessages) => currentMessages.slice(1))
    }

    const handleCloseDialog = () => {
        setDialogMessage(null)
    }

    return (
        <>
            <GlobalProgressBackdrop />
            <Snackbar
                autoHideDuration={snackbarAutoHideDuration}
                key={snackbarMessage?.id ?? 'dialog-service-snackbar'}
                onClose={handleCloseSnackbar}
                open={!!snackbarMessage}
                transitionDuration={SNACKBAR_TRANSITION_DURATION_MS}
            >
                <Alert
                    onClose={handleCloseSnackbarAlert}
                    severity={snackbarSeverity}
                    sx={{ width: '100%' }}
                    variant="filled"
                >
                    {snackbarMessage ? (
                        <SelectableAlertMessage message={snackbarMessage.message} />
                    ) : null}
                </Alert>
            </Snackbar>
            <Dialog aria-labelledby="dialog-service-title" open={!!dialogMessage}>
                <DialogTitle id="dialog-service-title">{dialogMessage?.title ?? 'Message'}</DialogTitle>
                <DialogContent>
                    <Alert severity={dialogSeverity}>
                        {dialogMessage ? (
                            <SelectableAlertMessage message={dialogMessage.message} />
                        ) : null}
                    </Alert>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleCloseDialog}>OK</Button>
                </DialogActions>
            </Dialog>
        </>
    )
}

import {
    Button,
    Checkbox,
    Dialog,
    DialogActions,
    DialogContent,
    DialogContentText,
    DialogTitle,
    FormControlLabel,
    TextField,
    Typography,
} from '@mui/material'
import type { ChangeEvent } from 'react'

interface WorktreeIntegrationDialogProps {
    busy: boolean
    commitMessage: string | null
    deleteBranch: boolean
    onClose: () => void
    onCommitMessageChange: (message: string) => void
    onDeleteBranchChange: (deleteBranch: boolean) => void
    onIntegrate: () => Promise<void>
    open: boolean
}

/** Confirms card worktree integration and optional local branch cleanup. */
export function WorktreeIntegrationDialog(props: WorktreeIntegrationDialogProps) {
    const {
        busy,
        commitMessage,
        deleteBranch,
        onClose,
        onCommitMessageChange,
        onDeleteBranchChange,
        onIntegrate,
        open,
    } = props
    const handleCommitMessageChange = (event: ChangeEvent<HTMLInputElement>) => onCommitMessageChange(event.target.value)
    const handleDeleteBranchChange = (event: ChangeEvent<HTMLInputElement>) => onDeleteBranchChange(event.target.checked)
    const integrateDisabled = busy || commitMessage !== null && commitMessage.trim().length === 0

    return (
        <Dialog fullWidth maxWidth="xs" onClose={busy ? undefined : onClose} open={open}>
            <DialogTitle>Integrate into project</DialogTitle>
            <DialogContent sx={{ display: 'flex', flexDirection: 'column', gap: 1, pt: 1 }}>
                <DialogContentText>Squash-merge card changes into project branch.</DialogContentText>
                {commitMessage !== null ? (
                    <>
                        <Typography color="text.secondary">Commit message</Typography>
                        <TextField
                            autoFocus
                            disabled={busy}
                            onChange={handleCommitMessageChange}
                            size="small"
                            value={commitMessage}
                        />
                    </>
                ) : null}
                <FormControlLabel
                    control={<Checkbox checked={deleteBranch} disabled={busy} onChange={handleDeleteBranchChange} />}
                    label="Delete branch"
                />
            </DialogContent>
            <DialogActions>
                <Button disabled={busy} onClick={onClose}>Cancel</Button>
                <Button disabled={integrateDisabled} onClick={onIntegrate} variant="contained">Integrate</Button>
            </DialogActions>
        </Dialog>
    )
}

